    for row in csv.DictReader(f):
        users.append({'id': str(int(row['id'].strip())), 'name': row['name'].strip(), 'country': row['country'].strip()})

totals = {u['id']: Decimal('0') for u in users}

def pick(d, *keys):
    for k in keys:
        if k in d and d[k] is not None:
            return d[k]
    return None

with open(os.path.join(HERE, 'orders.jsonl'), encoding='utf-8') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        o = json.loads(line)
        uid = pick(o, 'user_id', 'user', 'uid', 'customer_id')
        if uid is None:
            continue
        try:
            uid = str(int(str(uid).strip()))
        except ValueError:
            uid = str(uid).strip()
        status = pick(o, 'status')
        if status is None or str(status).strip().lower() != 'paid':
            continue
        total = pick(o, 'total', 'amount', 'total_amount')
        if total is None or uid not in totals:
            continue
        totals[uid] += Decimal(str(total).strip())

report = []
for u in users:
    pt = totals[u['id']].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    report.append({'user': u['name'], 'country': u['country'], 'paid_total': float(pt)})

report.sort(key=lambda r: (-r['paid_total'], r['user']))

with open(os.path.join(HERE, 'report.json'), 'w', encoding='utf-8') as f:
    json.dump(report, f, indent=2)
    f.write('\n')
